using Mcacc.Core.Model;
using Mcacc.Core.Terminal;
using Mcacc.Core.Tests.TestSupport;
using Shouldly;
using Xunit;

namespace Mcacc.Core.Tests.Terminal;

public class PosixCommandFileBuilderTests
{
    private static string LfLines(params string[] lines) => string.Concat(lines.Select(l => l + "\n"));

    [Fact]
    public void Profile_file_exports_the_config_dir_scrubs_sets_the_title_runs_claude_and_keeps_a_shell()
    {
        PosixCommandFileBuilder.Build(LaunchRequests.PosixProfile()).ShouldBe(LfLines(
            "#!/bin/zsh",
            "# Generated by MCACC - overwritten on every launch.",
            """export CLAUDE_CONFIG_DIR='/Users/Jö O'\''Neil’s 100%;$x/.mcacc/profiles/privat/claude'""",
            "unset " + Scrubs.Posix(ProviderDescriptors.Claude),
            @"cd ""$HOME"" || exit 1",
            @"printf '\033]0;%s\007' 'Claude Code · Privat'",
            @"""${SHELL:-/bin/zsh}"" -l -i -c 'claude'",
            @"exec ""${SHELL:-/bin/zsh}"" -l -i"));
    }

    [Fact]
    public void Codex_profile_file_exports_CODEX_HOME_and_runs_codex()
    {
        PosixCommandFileBuilder.Build(LaunchRequests.PosixCodexProfile()).ShouldBe(LfLines(
            "#!/bin/zsh",
            "# Generated by MCACC - overwritten on every launch.",
            """export CODEX_HOME='/Users/Jö O'\''Neil’s 100%;$x/.mcacc/profiles/codex-privat/codex'""",
            "unset " + Scrubs.Posix(ProviderDescriptors.Codex),
            @"cd ""$HOME"" || exit 1",
            @"printf '\033]0;%s\007' 'Codex · Codex Privat'",
            @"""${SHELL:-/bin/zsh}"" -l -i -c 'codex'",
            @"exec ""${SHELL:-/bin/zsh}"" -l -i"));
    }

    [Fact]
    public void Default_file_unsets_the_config_dir_variable()
    {
        var lines = PosixCommandFileBuilder.Build(LaunchRequests.PosixDefault()).Split('\n');

        lines[2].ShouldBe("unset CLAUDE_CONFIG_DIR");
        lines.Count(l => l.Contains("CLAUDE_CONFIG_DIR")).ShouldBe(1);
    }

    [Fact]
    public void Codex_default_file_unsets_CODEX_HOME()
    {
        var lines = PosixCommandFileBuilder.Build(LaunchRequests.PosixCodexDefault()).Split('\n');

        lines[2].ShouldBe("unset CODEX_HOME");
        lines.Count(l => l.Contains("CODEX_HOME")).ShouldBe(1);
    }

    /// <summary>
    /// The Codex sqlite home follows CODEX_HOME only when it is not set, so it must leave with the scrub list —
    /// otherwise a profile's databases stay in the default home.
    /// </summary>
    [Fact]
    public void Codex_file_unsets_the_sqlite_home_and_the_other_providers_config_dir()
    {
        var unset = PosixCommandFileBuilder.Build(LaunchRequests.PosixCodexProfile()).Split('\n')[3];

        unset.ShouldContain("CODEX_SQLITE_HOME");
        unset.ShouldContain("CLAUDE_CONFIG_DIR");
        unset.ShouldNotContain("CODEX_HOME ");
    }

    [Fact]
    public void Uses_lf_only_starts_with_the_shebang_and_ends_with_exec()
    {
        var content = PosixCommandFileBuilder.Build(LaunchRequests.PosixProfile());

        content.ShouldNotContain('\r');
        content.ShouldStartWith("#!/bin/zsh\n");
        content.ShouldEndWith("\n" + @"exec ""${SHELL:-/bin/zsh}"" -l -i" + "\n");
    }

    [Fact]
    public void Title_keeps_a_typographic_apostrophe_inside_single_quotes()
    {
        PosixCommandFileBuilder.Build(LaunchRequests.PosixProfile("Jö’s 'Firma'")).Split('\n')
            .ShouldContain(@"printf '\033]0;%s\007' 'Claude Code · Jö’s Firma'");
    }
}
